// Auto-generated by moshi-hook. Update with care.
//
// Lifecycle events are normalized here and written straight to the moshi-hook
// daemon socket (a named pipe on Windows) — no per-event helper spawn. When
// the daemon is absent the connect fails silently and the turn is never
// interrupted. Debug replay: pipe a normalized payload JSON into the CLI
// adapter, "moshi-hook pi-hook".
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent"
import { createConnection } from "node:net"
import { homedir } from "node:os"
import { join as pathJoin } from "node:path"
import { closeSync, openSync, readSync } from "node:fs"
import { spawn } from "node:child_process"

// Kept for debugging / manual replay through the CLI adapter above.
const helperBinary = "/opt/homebrew/bin/moshi-hook"

const agentSource = "pi"
const agentDisplayName = "Pi"

// Mirrors internal/config.SocketPath. The MOSHI_SOCKET_PATH override wins
// over the per-platform default so tests and dev daemons can point us at a
// throwaway socket.
function resolveSocketPath(): string {
  const override = process.env.MOSHI_SOCKET_PATH
  if (override) return override
  if (process.platform === "darwin") {
    return pathJoin(homedir(), "Library", "Application Support", "Moshi", "moshi-hook.sock")
  }
  if (process.platform === "win32") {
    return "\\\\.\\pipe\\moshi-hook"
  }
  if (process.env.XDG_RUNTIME_DIR) {
    return pathJoin(process.env.XDG_RUNTIME_DIR, "moshi-hook.sock")
  }
  return "/tmp/moshi-hook.sock"
}

// One-message-per-connection wire protocol (see internal/socket/server.go):
// dial, write one envelope as a JSON line, half-close, drain the daemon ack
// (so the daemon does not log broken pipes), close. Every failure resolves
// silently — hooks must never interrupt the user's Pi turn when
// Moshi is absent.
function sendEnvelope(envelope: Record<string, unknown>): void {
  try {
    const sock = createConnection({ path: resolveSocketPath() })
    sock.setNoDelay(true)
    sock.on("error", () => {
      try {
        sock.destroy()
      } catch {}
    })
    sock.once("connect", () => {
      sock.write(JSON.stringify(envelope) + "\n")
      sock.end()
    })
    sock.on("data", () => {})
  } catch {}
}

interface TerminalContext {
  terminalKind: string
  tmuxSession: string
  tmuxWindow: string
  tmuxPane: string
  tmuxSocket: string
  zellijSession: string
  zellijPane: string
  herdrSession: string
  herdrPane: string
  herdrWorkspaceId: string
  herdrWorkspace: string
  herdrTabId: string
  herdrTab: string
}

// Async spawn-and-capture. pi awaits every extension event handler, so the
// tmux roundtrip (~10ms warm, up to the timeout when the server is busy) must
// never run synchronously on a boot-path handler — callers await this only
// after their event handling is otherwise done.
function runForOutput(command: string, args: string[], timeout: number): Promise<string> {
  return new Promise((resolve) => {
    let stdout = ""
    let settled = false
    const done = (text: string) => {
      if (settled) return
      settled = true
      clearTimeout(timer)
      resolve(text)
    }
    let child: ReturnType<typeof spawn>
    let timer: ReturnType<typeof setTimeout>
    try {
      child = spawn(command, args, { stdio: ["ignore", "pipe", "ignore"], windowsHide: true })
      timer = setTimeout(() => child.kill(), timeout)
    } catch {
      resolve("")
      return
    }
    child.stdout?.on("data", (chunk: Buffer) => {
      stdout += chunk.toString("utf8")
    })
    child.on("error", () => done(""))
    child.on("close", () => done(stdout))
  })
}

function tmuxSocketFromEnv(value: string | undefined): string {
  if (!value) return ""
  const idx = value.indexOf(",")
  return idx > 0 ? value.slice(0, idx) : ""
}

async function resolveTerminalContext(): Promise<TerminalContext> {
  const tmuxPane = process.env.TMUX_PANE ?? ""
  const tmuxSocket = tmuxSocketFromEnv(process.env.TMUX)
  let tmuxSession = ""
  let tmuxWindow = ""
  if (process.env.TMUX) {
    const args = ["display-message", "-p"]
    if (tmuxPane) args.push("-t", tmuxPane)
    args.push("#S\t#I")
    const text = (await runForOutput("tmux", args, 200)).trim()
    if (text) {
      const parts = text.split("\t", 2)
      tmuxSession = parts[0] ?? ""
      tmuxWindow = parts[1] ?? ""
    }
  }
  const zellijSession = process.env.ZELLIJ_SESSION_NAME ?? ""
  const zellijPane = process.env.ZELLIJ_PANE_ID ?? ""
  // Herdr stamps pane identity into every pane's environment; labels are
  // resolved daemon-side from these ids, so no herdr CLI runs in-process.
  const inHerdr = process.env.HERDR_ENV === "1"
  const herdrSession = inHerdr ? process.env.HERDR_SESSION ?? "" : ""
  const herdrInfo = {
    paneId: inHerdr ? process.env.HERDR_PANE_ID ?? "" : "",
    workspaceId: inHerdr ? process.env.HERDR_WORKSPACE_ID ?? "" : "",
    workspace: "",
    tabId: inHerdr ? process.env.HERDR_TAB_ID ?? "" : "",
    tab: "",
  }
  let terminalKind = ""
  if (tmuxSession) terminalKind = "tmux"
  else if (process.env.HERDR_ENV === "1") terminalKind = "herdr"
  else if (process.env.ZELLIJ || zellijSession || zellijPane) terminalKind = "zellij"
  return {
    terminalKind,
    tmuxSession,
    tmuxWindow,
    tmuxPane,
    tmuxSocket,
    zellijSession,
    zellijPane,
    herdrSession,
    herdrPane: herdrInfo.paneId,
    herdrWorkspaceId: herdrInfo.workspaceId,
    herdrWorkspace: herdrInfo.workspace,
    herdrTabId: herdrInfo.tabId,
    herdrTab: herdrInfo.tab,
  }
}

// Started at module load but never awaited on the boot path: the tmux
// display-message roundtrip used to run synchronously here, blocking every
// launch inside tmux for ~10ms (250ms when the server was slow) before
// session_start could even fire. The first envelope is what needs the answer,
// and that fires well after pi's first paint.
const terminalContext = resolveTerminalContext()

function projectNameFromCwd(cwd: string): string {
  if (!cwd) return ""
  const trimmed = cwd.replace(/[\/\\]+$/, "")
  const idx = Math.max(trimmed.lastIndexOf("/"), trimmed.lastIndexOf("\\"))
  return idx >= 0 ? trimmed.slice(idx + 1) : trimmed
}

function projectNameForCwd(cwd: string, tc: TerminalContext): string {
  return tc.tmuxSession || tc.herdrSession || tc.zellijSession || projectNameFromCwd(cwd)
}

function firstString(...values: unknown[]): string {
  for (const value of values) {
    if (typeof value === "string" && value.length > 0) return value
  }
  return ""
}

function textFromContent(value: unknown): string {
  if (typeof value === "string") return value
  if (!Array.isArray(value)) return ""
  return value
    .map((chunk) => {
      if (typeof chunk === "string") return chunk
      if (chunk && typeof chunk === "object" && "text" in chunk) {
        const text = (chunk as { text?: unknown }).text
        return typeof text === "string" ? text : ""
      }
      return ""
    })
    .filter(Boolean)
    .join(" ")
}

function textFromMessage(value: unknown): string {
  if (!value || typeof value !== "object") return ""
  const message = value as Record<string, unknown>
  return firstString(
    textFromContent(message.content),
    textFromContent((message.message as Record<string, unknown> | undefined)?.content),
    textFromContent((message.entry as Record<string, unknown> | undefined)?.content),
  )
}

function modelLabel(model: unknown): string {
  if (!model || typeof model !== "object") return ""
  const obj = model as Record<string, unknown>
  return firstString(
    obj.displayName as string,
    obj.display_name as string,
    obj.name as string,
    obj.id as string,
    obj.modelId as string,
  )
}

function sessionID(event: Record<string, unknown>, ctx: Record<string, unknown>): string {
  const sessionManager = ctx.sessionManager as Record<string, unknown> | undefined
  const getSessionId = sessionManager?.getSessionId
  let managerID = ""
  if (typeof getSessionId === "function") {
    try {
      managerID = String(getSessionId.call(sessionManager) ?? "")
    } catch {}
  }
  return firstString(
    managerID,
    event.session_id as string,
    event.sessionId as string,
    "pi",
  )
}

function transcriptPath(ctx: Record<string, unknown>): string {
  const sessionManager = ctx.sessionManager as Record<string, unknown> | undefined
  const getSessionFile = sessionManager?.getSessionFile
  if (typeof getSessionFile !== "function") return ""
  try {
    return String(getSessionFile.call(sessionManager) ?? "")
  } catch {
    return ""
  }
}

function contextRemaining(ctx: Record<string, unknown>): number | undefined {
  const getContextUsage = ctx.getContextUsage
  if (typeof getContextUsage !== "function") return undefined
  try {
    const usage = getContextUsage.call(ctx) as { percent?: unknown } | undefined
    if (typeof usage?.percent !== "number" || !Number.isFinite(usage.percent)) return undefined
    return Math.max(1, Math.min(100, Math.round(100 - usage.percent)))
  } catch {
    return undefined
  }
}

function newSessionID(): string {
  const buf = new Uint8Array(16)
  try {
    crypto.getRandomValues(buf)
  } catch {
    for (let i = 0; i < buf.length; i += 1) buf[i] = Math.floor(Math.random() * 256)
  }
  return Array.from(buf, (b) => b.toString(16).padStart(2, "0")).join("")
}

// Markdown stripping mirrors stripMarkdown in
// internal/cli/hook_claude_transcript.go: code blocks dropped wholesale,
// inline pairs keep their text, everything collapses to one line.
// \u0060 is a backtick — the enclosing Go raw string cannot contain one.
const mdCodeBlock = /\u0060\u0060\u0060[a-zA-Z0-9_-]*\n[\s\S]*?\u0060\u0060\u0060/g
const mdInlineCode = /\u0060([^\u0060]*)\u0060/g
const mdLink = /\[([^\]]+)\]\([^)]+\)/g
const mdBoldStar = /\*\*([^*]+)\*\*/g
const mdBoldUnder = /__([^_]+)__/g
const mdItalicStar = /(^|[^*])\*([^*\n]+)\*/g
const mdItalicUnder = /(^|[^_])_([^_\n]+)_/g
const mdLineNoise = /^\s*(#{1,6}\s+|[>\-*+]\s+|\d+\.\s+)/gm
const mdWhitespace = /\s+/g

function stripMarkdown(s: string): string {
  if (!s) return ""
  s = s.replace(mdCodeBlock, "")
  s = s.replace(mdInlineCode, "$1")
  s = s.replace(mdLink, "$1")
  s = s.replace(mdBoldStar, "$1")
  s = s.replace(mdBoldUnder, "$1")
  s = s.replace(mdItalicStar, "$1$2")
  s = s.replace(mdItalicUnder, "$1$2")
  s = s.replace(mdLineNoise, "")
  s = s.replace(mdWhitespace, " ")
  return s.trim()
}

function truncateText(s: string, n: number): string {
  const chars = Array.from(s)
  if (chars.length <= n) return s
  return chars.slice(0, Math.max(0, n - 1)).join("") + "…"
}

function plainTextClip(s: string, n: number): string {
  return truncateText(stripMarkdown(s), n)
}

// displayUserPrompt mirrors internal/cli/hook_more_agents.go: agents that
// wrap the typed ask in <user_query> (or append skill/system blocks) should
// not leak that markup into the "You:" subtitle.
const userQueryRe = /<user_query>\s*([\s\S]*?)\s*<\/user_query>/i
const skillInfoRe = /<skill_information>[\s\S]*?<\/skill_information>/gi
const imageFilesRe = /<image_files>[\s\S]*?<\/image_files>/gi
const systemRemRe = /<system-reminder>[\s\S]*?<\/system-reminder>/gi

function displayUserPrompt(s: string): string {
  s = s.trim()
  if (!s) return ""
  const m = userQueryRe.exec(s)
  if (m?.[1]) return m[1].trim()
  s = s.replace(skillInfoRe, "").replace(imageFilesRe, "").replace(systemRemRe, "")
  return s.trim()
}

function formatUserPromptDetail(prompt: string): string {
  const s = plainTextClip(displayUserPrompt(prompt), 200)
  return s ? "You: " + s : ""
}

// Per-session bookkeeping, the in-process equivalent of the CLI adapter's
// internal/agentstate files. The extension lives as long as the agent
// process, so plain maps carry state across events.
interface SessionState {
  model: string
  transcriptPath: string
  sessionStartTime: number
  firstPromptPushedAt: number
  lastUserPrompt: string
  lastEventTitle: string
  lastToolName: string
  promptSequence: number
  completedPromptSequence: number
  lastStopTime: number
  lastStopSignature: string
}

const sessions = new Map<string, SessionState>()

function stateFor(sessionId: string): SessionState {
  let state = sessions.get(sessionId)
  if (!state) {
    state = {
      model: "",
      transcriptPath: "",
      sessionStartTime: 0,
      firstPromptPushedAt: 0,
      lastUserPrompt: "",
      lastEventTitle: "",
      lastToolName: "",
      promptSequence: 0,
      completedPromptSequence: 0,
      lastStopTime: 0,
      lastStopSignature: "",
    }
    sessions.set(sessionId, state)
  }
  return state
}

function nowSeconds(): number {
  return Date.now() / 1000
}

// Mirrors internal/agentstate.PromptSequenceForSubmit: reuse the in-flight
// turn's number, or advance when the previous turn already completed.
function promptSequenceForSubmit(state: SessionState): number {
  if (state.promptSequence === 0) return 1
  if (state.completedPromptSequence >= state.promptSequence) return state.promptSequence + 1
  return state.promptSequence
}

// Mirrors recordTaskCompletion in internal/cli/hook_more_agents.go: suppress
// duplicate stop events inside a short cooldown once the turn completed.
const stopCooldownSeconds = 5

function recordTaskCompletion(state: SessionState, signature: string, now: number): boolean {
  if (!signature) signature = agentSource + "-complete"
  const turnAlreadyCompleted = state.promptSequence === 0 || state.promptSequence <= state.completedPromptSequence
  if (turnAlreadyCompleted && state.lastStopTime > 0 && now - state.lastStopTime < stopCooldownSeconds &&
    signature === state.lastStopSignature) {
    return false
  }
  state.lastStopTime = now
  state.lastStopSignature = signature
  if (state.promptSequence > 0) state.completedPromptSequence = state.promptSequence
  return true
}

// Pi's versioned SessionHeader writes parentSession(-Id) when a session was
// created by fork/clone/newSession with lineage; child sessions stay out of
// the inbox. Lineage cannot change for a live transcript, so a successful
// read is cached per path; an unreadable or half-written header is retried
// on the next event.
const transcriptChildCache = new Map<string, boolean>()

function sessionIsChild(state: SessionState, payload: HookPayload): boolean {
  if (agentSource !== "pi") return false
  const path = payload.transcript_path || state.transcriptPath
  if (!path) return false
  const cached = transcriptChildCache.get(path)
  if (cached !== undefined) return cached
  const child = transcriptHeaderIsChild(path)
  if (child === null) return false
  transcriptChildCache.set(path, child)
  return child
}

function transcriptHeaderIsChild(path: string): boolean | null {
  let fd: number
  try {
    fd = openSync(path, "r")
  } catch {
    return null
  }
  try {
    const buf = Buffer.alloc(16 * 1024)
    const n = readSync(fd, buf, 0, buf.length, 0)
    const text = buf.subarray(0, n).toString("utf8")
    const nl = text.indexOf("\n")
    const header = JSON.parse(nl >= 0 ? text.slice(0, nl) : text) as Record<string, unknown>
    return firstString(header.parentSession, header.parentSessionId) !== ""
  } catch {
    return null
  } finally {
    try {
      closeSync(fd)
    } catch {}
  }
}

interface HookPayload {
  hook_event_name: string
  session_id: string
  transcript_path: string
  cwd: string
  model: string
  context_remaining: number | undefined
  [key: string]: unknown
}

async function baseEnvelope(
  payload: HookPayload,
  sessionId: string,
  eventName: string,
): Promise<Record<string, unknown>> {
  const tc = await terminalContext
  const envelope: Record<string, unknown> = {
    type: "session.update",
    source: agentSource,
    sessionId,
    eventName,
    cwd: payload.cwd,
    projectName: projectNameForCwd(payload.cwd, tc),
    terminalKind: tc.terminalKind,
    tmuxSession: tc.tmuxSession,
    tmuxWindow: tc.tmuxWindow,
    tmuxPane: tc.tmuxPane,
    tmuxSocket: tc.tmuxSocket,
    zellijSession: tc.zellijSession,
    zellijPane: tc.zellijPane,
    herdrSession: tc.herdrSession,
    herdrPane: tc.herdrPane,
    herdrWorkspaceId: tc.herdrWorkspaceId,
    herdrWorkspace: tc.herdrWorkspace,
    herdrTabId: tc.herdrTabId,
    herdrTab: tc.herdrTab,
    modelName: payload.model,
    transcriptPath: payload.transcript_path,
    requestedAt: new Date().toISOString(),
  }
  if (typeof payload.context_remaining === "number" && payload.context_remaining > 0) {
    envelope.contextRemaining = Math.round(payload.context_remaining)
  }
  return envelope
}

// handleEvent is the in-module port of runPiFamilyHook in
// internal/cli/hook_more_agents.go. Async only because baseEnvelope awaits the
// terminal-context promise; every state mutation below happens synchronously
// before that await, so rapid-fire events cannot interleave the bookkeeping.
async function handleEvent(payload: HookPayload): Promise<void> {
  const sessionId = payload.session_id || newSessionID()
  const state = stateFor(sessionId)
  const isChild = sessionIsChild(state, payload)
  switch (payload.hook_event_name) {
    case "SessionStart": {
      if (payload.model) state.model = payload.model
      if (payload.transcript_path) state.transcriptPath = payload.transcript_path
      state.sessionStartTime = nowSeconds()
      if (state.promptSequence > state.completedPromptSequence) {
        state.completedPromptSequence = state.promptSequence
      }
      // A category-less update is a silent state carrier: the daemon persists
      // the transcript path / model / pane for Chat View without publishing
      // anything — the first prompt announces the session.
      sendEnvelope(await baseEnvelope(payload, sessionId, "SessionStart"))
      return
    }
    case "SessionEnd": {
      if (isChild) return
      const envelope = await baseEnvelope(payload, sessionId, "SessionEnd")
      envelope.type = "session.closed"
      envelope.category = "session_ended"
      envelope.title = agentDisplayName + " session ended"
      sendEnvelope(envelope)
      return
    }
    case "UserPromptSubmit": {
      if (isChild) return
      state.lastUserPrompt = plainTextClip(displayUserPrompt(firstString(payload.prompt)), 256)
      state.promptSequence = promptSequenceForSubmit(state)
      const alreadyPushed = state.firstPromptPushedAt !== 0 && state.firstPromptPushedAt >= state.sessionStartTime
      if (!alreadyPushed) state.firstPromptPushedAt = nowSeconds()
      let title = agentDisplayName + " session started"
      if (alreadyPushed && state.lastEventTitle) title = state.lastEventTitle
      const envelope = await baseEnvelope(payload, sessionId, alreadyPushed ? "UserPromptSubmit" : "SessionStart")
      envelope.category = "session_started"
      envelope.title = title
      envelope.message = formatUserPromptDetail(state.lastUserPrompt)
      state.lastEventTitle = title
      sendEnvelope(envelope)
      return
    }
    case "AgentStart":
      return
    case "PermissionRequest": {
      // Pi owns the approval prompt and decision. Moshi mirrors
      // the waiting state; with a verified terminal target the daemon's TUI
      // bridge can send the user's remote decision into the native prompt.
      const toolName = firstString(payload.tool_name)
      state.lastToolName = toolName
      const title = agentDisplayName + " needs approval"
      const envelope = await baseEnvelope(payload, sessionId, "PermissionRequest")
      envelope.actionId = firstString(payload.tool_use_id) || newSessionID()
      envelope.phase = "waitingForApproval"
      envelope.category = "approval_required"
      envelope.toolName = toolName
      envelope.title = title
      envelope.subtitle = "Answer in terminal"
      envelope.message = plainTextClip(firstString(payload.reason, payload.description), 256)
      state.lastEventTitle = title
      sendEnvelope(envelope)
      return
    }
    case "PermissionResolved": {
      const title = agentDisplayName + " resumed"
      const envelope = await baseEnvelope(payload, sessionId, "PermissionResolved")
      envelope.category = "session_started"
      envelope.title = title
      envelope.message = formatUserPromptDetail(state.lastUserPrompt)
      envelope.toolName = state.lastToolName
      state.lastEventTitle = title
      sendEnvelope(envelope)
      return
    }
    case "AgentEnd":
    case "TurnEnd": {
      if (isChild) return
      const assistant = firstString(payload.last_assistant_message)
      if (!recordTaskCompletion(state, plainTextClip(assistant, 200), nowSeconds())) return
      const title = plainTextClip(assistant, 80) || agentDisplayName + " complete"
      const envelope = await baseEnvelope(payload, sessionId, payload.hook_event_name)
      envelope.category = "task_complete"
      envelope.title = title
      envelope.message = formatUserPromptDetail(state.lastUserPrompt)
      state.lastEventTitle = title
      sendEnvelope(envelope)
      return
    }
    default:
      sendEnvelope(await baseEnvelope(payload, sessionId, payload.hook_event_name))
  }
}

function send(eventName: string, event: unknown, ctx: unknown, extra: Record<string, unknown> = {}) {
  const eventObj = event && typeof event === "object" ? event as Record<string, unknown> : {}
  const ctxObj = ctx && typeof ctx === "object" ? ctx as Record<string, unknown> : {}
  const payload: HookPayload = {
    hook_event_name: eventName,
    session_id: sessionID(eventObj, ctxObj),
    transcript_path: transcriptPath(ctxObj),
    cwd: firstString(ctxObj.cwd as string, process.cwd()),
    model: modelLabel(ctxObj.model),
    context_remaining: contextRemaining(ctxObj),
    ...extra,
  }

  // Fire-and-forget: pi awaits event handlers, and the daemon write must never
  // hold an event open. Hooks never interrupt the user's Pi turn anyway.
  void handleEvent(payload).catch(() => {
    // Hooks should never interrupt the user's Pi turn.
  })
}

export default function moshiPiHook(pi: ExtensionAPI): void {
  pi.on("session_start", (event, ctx) => {
    send("SessionStart", event, ctx)
  })



  pi.on("before_agent_start", (event, ctx) => {
    send("UserPromptSubmit", event, ctx, { prompt: event.prompt })
  })

  pi.on("agent_start", (event, ctx) => {
    send("AgentStart", event, ctx)
  })

  let lastAssistantMessage = ""

  pi.on("agent_end", (event) => {
    const messages = Array.isArray(event.messages) ? event.messages : []
    for (let index = messages.length - 1; index >= 0; index -= 1) {
      const message = messages[index] as unknown as Record<string, unknown>
      if (message?.role === "assistant") {
        lastAssistantMessage = textFromMessage(message)
        break
      }
    }
  })

  pi.on("agent_settled", (event, ctx) => {
    send("AgentEnd", event, ctx, { last_assistant_message: lastAssistantMessage })
    lastAssistantMessage = ""
  })



  pi.on("session_shutdown", (event, ctx) => {
    send("SessionEnd", event, ctx)
  })
}
